CREATE TABLE IF NOT EXISTS billing.document_types (
 "TenantId" uuid NOT NULL, "LegalEntityId" uuid NOT NULL, "Id" uuid NOT NULL, "Version" integer NOT NULL CHECK ("Version">0),
 "Code" varchar(30) NOT NULL, "WorkshopSourceAllowed" boolean NOT NULL, "ConfirmationAllowed" boolean NOT NULL,
 PRIMARY KEY ("TenantId","LegalEntityId","Id","Version")
);

CREATE TABLE IF NOT EXISTS billing.invoice_confirmations (
 "InvoiceId" uuid PRIMARY KEY REFERENCES billing.invoices("Id"),
 "Id" uuid NOT NULL UNIQUE CHECK ("Id" <> '00000000-0000-0000-0000-000000000000'), "TenantId" uuid NOT NULL,
 "ConfigurationVersion" integer NOT NULL CHECK ("ConfigurationVersion">0), "Issuer" jsonb NOT NULL, "Recipient" jsonb NOT NULL,
 "ConfirmedAt" timestamptz NOT NULL, "ConfirmedBy" uuid NOT NULL
);

CREATE TABLE IF NOT EXISTS billing.invoice_journal_links (
 "InvoiceId" uuid PRIMARY KEY REFERENCES billing.invoice_confirmations("InvoiceId"), "TenantId" uuid NOT NULL,
 "JournalEntryId" uuid NOT NULL UNIQUE, "LinkedAt" timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS billing.issuer_profiles (
 "TenantId" uuid NOT NULL, "LegalEntityId" uuid NOT NULL, "Version" integer NOT NULL CHECK ("Version">0),
 "LegalName" varchar(100) NOT NULL, "FiscalIdentifier" varchar(40) NOT NULL, "RegisteredOffice" varchar(200) NOT NULL,
 PRIMARY KEY ("TenantId","LegalEntityId","Version")
);

CREATE TABLE IF NOT EXISTS counterparties.destinations (
 "Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL, "CounterpartyId" uuid NOT NULL,
 "OwnerLegalEntityId" uuid NOT NULL, "Address" varchar(500) NOT NULL CHECK(length(btrim("Address")) BETWEEN 1 AND 500),
 "Published" boolean NOT NULL DEFAULT false,
 FOREIGN KEY ("CounterpartyId", "TenantId") REFERENCES counterparties.counterparties("Id", "TenantId")
);

CREATE TABLE IF NOT EXISTS integrations.administrative_reconciliations (
 "Id" uuid PRIMARY KEY CHECK ("Id" <> '00000000-0000-0000-0000-000000000000'),
 "TenantId" uuid NOT NULL, "RequestId" uuid NOT NULL REFERENCES integrations.administrative_dispatches("RequestId"),
 "OperatorId" uuid NOT NULL, "RequestedAt" timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS inventory.stock (
 "TenantId" uuid NOT NULL, "LegalEntityId" uuid NOT NULL, "SiteId" uuid NOT NULL,
 "WarehouseId" uuid NOT NULL, "CatalogItemId" uuid NOT NULL,
 "Physical" numeric(12,6) NOT NULL CHECK ("Physical">=0),
 PRIMARY KEY ("TenantId","LegalEntityId","SiteId","WarehouseId","CatalogItemId")
);

CREATE TABLE IF NOT EXISTS organization_access.capability_activations (
    "LegalEntityId" uuid NOT NULL REFERENCES organization_access.legal_entities ("Id") ON DELETE CASCADE,
    "Capability" varchar(100) NOT NULL,
    "Enabled" boolean NOT NULL,
    PRIMARY KEY ("LegalEntityId", "Capability")
);

CREATE TABLE IF NOT EXISTS organization_access.common_edit_permissions (
 "MembershipId" uuid NOT NULL, "TenantId" uuid NOT NULL,
 PRIMARY KEY ("MembershipId", "TenantId"),
 FOREIGN KEY ("MembershipId", "TenantId") REFERENCES organization_access.memberships("Id", "TenantId")
);

CREATE TABLE organization_access.external_identity_bindings (
    "InternalIdentityId" uuid PRIMARY KEY CHECK (
        "InternalIdentityId" <> '00000000-0000-0000-0000-000000000000'::uuid
    ),
    "Issuer" text COLLATE "C" NOT NULL CHECK (
        octet_length("Issuer") BETWEEN 9 AND 2048
        AND "Issuer" ~ '^https://[^[:space:]?#]+$'
    ),
    "Subject" varchar(255) COLLATE "C" NOT NULL CHECK (
        octet_length("Subject") BETWEEN 1 AND 255
        AND "Subject" ~ '^[ -~]+$'
    ),
    UNIQUE ("Issuer", "Subject")
);

CREATE TABLE IF NOT EXISTS organization_access.legal_entities (
    "Id" uuid PRIMARY KEY,
    "TenantId" uuid NOT NULL REFERENCES organization_access.tenants ("Id") ON DELETE CASCADE,
    "Name" varchar(100) NOT NULL,
    UNIQUE ("Id", "TenantId")
);

CREATE TABLE IF NOT EXISTS organization_access.memberships (
    "Id" uuid PRIMARY KEY,
    "TenantId" uuid NOT NULL REFERENCES organization_access.tenants ("Id") ON DELETE CASCADE,
    "IdentitySubject" varchar(200) NOT NULL,
    UNIQUE ("Id", "TenantId")
);

CREATE TABLE IF NOT EXISTS organization_access.tenants (
    "Id" uuid PRIMARY KEY,
    "Name" varchar(100) NOT NULL
);

CREATE TABLE workshop.actual_time_group_references (
 "TenantId" uuid NOT NULL, "OrderId" uuid NOT NULL, "WorkingGroupId" uuid NOT NULL,
 PRIMARY KEY ("TenantId","OrderId","WorkingGroupId"),
 FOREIGN KEY ("TenantId","OrderId","WorkingGroupId") REFERENCES workshop.working_groups ("TenantId","OrderId","Id")
);

CREATE TABLE IF NOT EXISTS workshop.administrative_outbox (
 "RequestId" uuid PRIMARY KEY REFERENCES workshop.administrative_requests("Id"),
 "TenantId" uuid NOT NULL,
 "CreatedAt" timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS workshop.line_policies (
 "TenantId" uuid NOT NULL, "LegalEntityId" uuid NOT NULL, "DocumentTypeId" uuid NOT NULL,
 "Version" integer NOT NULL CHECK ("Version">0), "Policy" varchar(30) NOT NULL, "SameWorkingGroup" boolean NOT NULL,
 PRIMARY KEY ("TenantId","LegalEntityId","DocumentTypeId","Version")
);

CREATE TABLE workshop.own_actual_time_commands (
 "CommandId" uuid PRIMARY KEY CHECK ("CommandId" <> '00000000-0000-0000-0000-000000000000'),
 "TenantId" uuid NOT NULL, "OrderId" uuid NOT NULL, "MembershipId" uuid NOT NULL, "InternalIdentityId" uuid NOT NULL,
 "EntryId" uuid NOT NULL, "Canonical" jsonb NOT NULL, "Receipt" jsonb NOT NULL,
 FOREIGN KEY ("TenantId","OrderId","MembershipId","EntryId","InternalIdentityId") REFERENCES workshop.own_actual_time_entries ("TenantId","OrderId","MembershipId","Id","InternalIdentityId")
);

CREATE TABLE workshop.own_actual_time_streams (
 "TenantId" uuid NOT NULL, "OrderId" uuid NOT NULL, "MembershipId" uuid NOT NULL CHECK ("MembershipId" <> '00000000-0000-0000-0000-000000000000'),
 "Revision" integer NOT NULL CHECK ("Revision">=0),
 PRIMARY KEY ("TenantId","OrderId","MembershipId"),
 FOREIGN KEY ("TenantId","OrderId") REFERENCES workshop.orders ("TenantId","Id")
);
